  );
}

/* ==========================================================================
   WIDGET 위젯 — spatial glass dashboard · visionOS style
   glass-futurism · depth gradient / suspended glass widgets / iris accent
   Scoped by convention to .widget-root; classes prefixed widget-.
   Crafted to the gallery glass-futurism benchmark (see CRAFT-STANDARDS.md):
   backdrop-filter blur(12px) saturate(160%), rgba(255,255,255,0.12) surfaces,
   multi-layer shadow (ambient + key + contact), per-property transitions.
   ========================================================================== */

.widget-root {
  /* ---- Depth + glass surfaces -----------------------------------------
     Contrast ratios verified against the depth gradient ground
     (#1a1830 → #2a1f4a, treated as ~#211a3c for measurement).             */
  --w-depth-1: #1a1830;     /* ink-violet — ground top                      */
  --w-depth-2: #2a1f4a;     /* iris-violet — ground bottom                  */
  --w-depth-3: #150f28;     /* near-black — far edges, vignette             */
  --w-glass:          rgba(255, 255, 255, 0.12);  /* surface alpha — std    */
  --w-glass-deep:     rgba(255, 255, 255, 0.16);  /* hover/active lift      */
  --w-glass-faint:    rgba(255, 255, 255, 0.06);  /* recessed fields        */
  --w-glass-border:   rgba(255, 255, 255, 0.25);  /* hairline edge — a11y   */
  --w-glass-edge:     rgba(255, 255, 255, 0.40);  /* inner light facet      */
  --w-iris:           #6366f1;  /* indigo-500 · on ground 3.0:1 — large/
                                   decorative only; never body text          */
  --w-iris-bright:    #818cf8;  /* indigo-400 · on ground 4.2:1 — large     */
  --w-iris-glow:      rgba(99, 102, 241, 0.45);
  --w-iris-soft:      rgba(99, 102, 241, 0.22);
  --w-aqua:           #22d3ee;  /* cyan-400 · on ground 8.9:1 (AAA)         */
  --w-rose:            #fb7185;  /* rose-400 · on ground 5.0:1 (AA)         */
  --w-emerald:         #34d399;  /* emerald-400 · on ground 9.1:1 (AAA)     */
  --w-text:           #f4f3ff;  /* paper-violet · on ground 15.4:1 (AAA)    */
  --w-text-dim:       #b4b2d6;  /* mute-violet  · on ground  8.4:1 (AAA)    */
  --w-text-faint:     #8a87a8;  /* fade-violet  · on ground  5.4:1 (AA)     */

  --w-font-sans:  "Inter", sans-serif;
  --w-font-kr:    "Noto Sans KR", sans-serif;
  --w-font-stack: "Inter", "Noto Sans KR", sans-serif;

  /* ---- Intent-separated easing curves --------------------------------
     Never default ease/linear; never `transition: all` (see std §1, §7).   */
  --w-ease-reveal: cubic-bezier(0.16, 1, 0.3, 1);    /* entry / reveal     */
  --w-ease-hover:  cubic-bezier(0.25, 1, 0.5, 1);    /* hover / scrub      */
  --w-ease-back:   cubic-bezier(0.34, 1.56, 0.64, 1);/* press micro-bounce */

  /* ---- Fluid type scale (Major Third 1.320) -------------------------- */
  --w-step--1: clamp(0.78rem, 0.75rem + 0.14vw, 0.88rem); /* caption       */
  --w-step-0:  clamp(0.94rem, 0.89rem + 0.24vw, 1.12rem); /* body          */
  --w-step-1:  clamp(1.24rem, 1.16rem + 0.38vw, 1.46rem); /* card title    */
  --w-step-2:  clamp(1.64rem, 1.51rem + 0.61vw, 2.00rem); /* h3            */
  --w-step-3:  clamp(2.16rem, 1.97rem + 0.96vw, 2.77rem); /* h2            */
  --w-step-4:  clamp(2.86rem, 2.57rem + 1.45vw, 3.82rem); /* h1            */
  --w-step-5:  clamp(3.77rem, 3.30rem + 2.14vw, 5.28rem); /* display       */

  /* ---- 4px baseline spacing scale ------------------------------------ */
  --w-sp-1: 0.25rem;   /*  4px */
  --w-sp-2: 0.5rem;    /*  8px — base unit */
  --w-sp-3: 0.75rem;   /* 12px */
  --w-sp-4: 1rem;      /* 16px */
  --w-sp-5: 1.25rem;   /* 20px */
  --w-sp-6: 1.5rem;    /* 24px */
  --w-sp-7: 1.75rem;   /* 28px */
  --w-sp-8: 2rem;      /* 32px */
  --w-sp-10: 2.5rem;   /* 40px */
  --w-sp-12: 3rem;     /* 48px */
  --w-sp-16: 4rem;     /* 64px */

  /* ---- Multi-layer glass shadow (ambient + key + contact) -------------
     The card hovers, so it needs a top bevel (inset highlight), an ambient
     contact, a key cast, and a far diffusion — four layers, not one.       */
  --w-shadow-card:
    inset 0 1px 0  rgba(255, 255, 255, 0.12),  /* top facet — bevel        */
    inset 0 0 0 1px rgba(255, 255, 255, 0.03), /* inner light shell         */
    0 2px 4px      rgba(0, 0, 0, 0.28),        /* ambient — surface contact */
    0 14px 32px    rgba(0, 0, 0, 0.42),        /* key — primary cast        */
    0 40px 80px    rgba(0, 0, 0, 0.36);        /* contact — far diffusion   */
  --w-shadow-card-lift:
    inset 0 1px 0  rgba(255, 255, 255, 0.18),
    inset 0 0 0 1px rgba(255, 255, 255, 0.05),
    0 2px 6px      rgba(0, 0, 0, 0.32),
    0 22px 44px    rgba(99, 102, 241, 0.22),
    0 56px 100px   rgba(0, 0, 0, 0.44);
  /* Contact drop-shadow — grounds the floating glass in space, distinct
     from the box-shadow cast (std §product-3d: drop-shadow for contact).   */
  --w-contact-near:  drop-shadow(0 36px 48px rgba(0, 0, 0, 0.40));
  --w-contact-mid:   drop-shadow(0 26px 38px rgba(0, 0, 0, 0.34));
  --w-contact-far:   drop-shadow(0 18px 26px rgba(0, 0, 0, 0.28));

  /* Parallax custom properties written by usePointerParallax per card.
     Resting state is flat — the dashboard is complete without motion.      */
  --w-rx: 0deg;
  --w-ry: 0deg;
  --w-lift: 0px;

  position: relative;
  min-height: 100vh;
  background:
    radial-gradient(120% 80% at 50% -10%, rgba(99, 102, 241, 0.16), transparent 60%),
    linear-gradient(160deg, var(--w-depth-1) 0%, var(--w-depth-2) 55%, var(--w-depth-3) 100%);
  color: var(--w-text);
  font-family: var(--w-font-stack);
  font-weight: 400;
  font-size: var(--w-step-0);
  line-height: 1.6;
  letter-spacing: -0.011em;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
  overflow-x: clip;
}

/* ==========================================================================
   Aurora ground — three slow iris blooms drifting behind the glass, the
   ambient light of a spatial OS. Pure CSS, paused under reduced motion.
   ========================================================================== */
.widget-aurora {
  position: absolute;
  inset: -8%;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
  border-radius: 32px;
}
.widget-aurora__blob {
  position: absolute;
  display: block;
  border-radius: 50%;
  filter: blur(48px);
  opacity: 0.55;
  will-change: transform;
}
.widget-aurora__blob--a {
  width: 46vw;
  height: 46vw;
  left: 4%;
  top: 8%;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.55), transparent 68%);
  animation: widget-drift-a 26s var(--w-ease-hover) infinite alternate;
}
.widget-aurora__blob--b {
  width: 40vw;
  height: 40vw;
  right: 2%;
  top: 30%;
  background: radial-gradient(circle, rgba(168, 85, 247, 0.45), transparent 68%);
  animation: widget-drift-b 31s var(--w-ease-hover) infinite alternate;
}
.widget-aurora__blob--c {
  width: 36vw;
  height: 36vw;
  left: 30%;
  bottom: 4%;
  background: radial-gradient(circle, rgba(34, 211, 238, 0.32), transparent 68%);
  animation: widget-drift-c 37s var(--w-ease-hover) infinite alternate;
}
@keyframes widget-drift-a { to { transform: translate3d(8%, -6%, 0) scale(1.12); } }
@keyframes widget-drift-b { to { transform: translate3d(-7%, 5%, 0) scale(1.08); } }
@keyframes widget-drift-c { to { transform: translate3d(5%, -4%, 0) scale(1.15); } }
@media (prefers-reduced-motion: reduce) {
  .widget-aurora__blob { animation: none; }
}

.widget-doc { position: relative; z-index: 1; }

/* Korean needs its own metrics — Hangul never gets tracking fanned out. */
.widget-root :lang(ko) {
  font-family: var(--w-font-kr);
  letter-spacing: 0;
  line-height: 1.9;
  word-break: keep-all;
  word-wrap: break-word;
}
.widget-root ::selection {
  background: var(--w-iris);
  color: #fff;
}
.widget-root :focus-visible {
  outline: 2px solid var(--w-iris-bright);
  outline-offset: 4px;
  border-radius: 4px;
}

/* ==========================================================================
   Reveal — direction-aware clip-path, JS-gated. With no .widget-js the SSR
   markup is the finished dashboard; the pre-reveal hidden state only applies
   once JS is alive. Under reduced motion, blocks just stand.
   ========================================================================== */
.widget-js [data-reveal] {
  opacity: 0;
  transform: translateY(22px);
  clip-path: inset(0 0 100% 0);
  transition:
    opacity 700ms var(--w-ease-reveal),
    transform 700ms var(--w-ease-reveal),
    clip-path 760ms var(--w-ease-reveal);
}
.widget-js [data-reveal].is-revealed {
  opacity: 1;
  transform: none;
  clip-path: inset(0);
}
@media (prefers-reduced-motion: reduce) {
  .widget-js [data-reveal] {
    opacity: 1;
    transform: none;
    clip-path: none;
    transition: none;
  }
}

/* Visually hidden but accessible. */
.widget-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ==========================================================================
   Hero — the spatial sign-in
   ========================================================================== */
.widget-hero {
  padding:
    clamp(72px, 14vh, 132px) clamp(20px, 5vw, 60px) clamp(32px, 6vh, 56px);
  text-align: center;
}
.widget-kicker {
  font-size: var(--w-step--1);
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--w-iris-bright);
  margin: 0 0 var(--w-sp-5);
  text-wrap: pretty;
}
.widget-title {
  font-weight: 700;
  font-size: var(--w-step-5);
  line-height: 1;
  letter-spacing: -0.04em;          /* display tracking — major glyph run  */
  margin: 0 0 var(--w-sp-5);
  text-wrap: balance;
}
.widget-title :lang(ko) {
  font-size: 0.48em;
  color: var(--w-iris-bright);
  letter-spacing: 0;
  font-weight: 600;
}
.widget-sub {
  color: var(--w-text-dim);
  font-size: var(--w-step-1);
  max-width: 36ch;
  margin: 0 auto;
  text-wrap: pretty;
}

/* ==========================================================================
   Stage section — the spatial field
   ========================================================================== */
.widget-stage-section {
  position: relative;
  padding: clamp(24px, 5vh, 48px) clamp(16px, 4vw, 48px) clamp(48px, 10vh, 96px);
}
.widget-stage-meta {
  display: flex;
  align-items: baseline;
  gap: var(--w-sp-3);
  max-width: 1200px;
  margin: 0 auto var(--w-sp-6);
  font-size: var(--w-step--1);
  color: var(--w-text-faint);
  text-transform: uppercase;
  letter-spacing: 0.18em;
}
.widget-stage-meta__no {
  color: var(--w-iris-bright);
  font-variant-numeric: tabular-nums;
}
.widget-stage-meta__label { color: var(--w-text-dim); }
.widget-stage-meta__hint {
  margin-left: auto;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--w-text-faint);
}

/* ==========================================================================
   Stage — the perspective container. The pointer surface for the parallax
   hook. perspective 1000px + preserve-3d so children genuinely occupy depth.
   ========================================================================== */
.widget-stage {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
  padding: clamp(20px, 4vw, 40px);
  border-radius: 36px;
  perspective: 1200px;
  perspective-origin: 50% 42%;
  min-height: 520px;
}

/* Grid of widgets — bento spans via custom properties (mobile collapses). */
.widget-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: minmax(120px, auto);
  gap: clamp(14px, 1.6vw, 22px);
  grid-auto-flow: dense;
  transform-style: preserve-3d;
}
.widget-cell {
  grid-column: span min(var(--w-span-col, 2), 4);
  grid-row: span var(--w-span-row, 1);
  /* Stagger the reveal by order index set inline. */
  transition: none;
}
.widget-js .widget-cell {
  opacity: 0;
  transform: translateZ(-120px) translateY(16px);
  transition:
    opacity 600ms var(--w-ease-reveal),
    transform 700ms var(--w-ease-reveal);
  transition-delay: calc(var(--w-i, 0) * 70ms);
}
.widget-js .widget-cell.is-revealed,
.widget-js [data-reveal].is-revealed .widget-cell {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .widget-js .widget-cell {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* ==========================================================================
   WidgetCard — the glass shell. The 3D transform composes the resting tilt
   with the live parallax vars; preserve-3d keeps the face in space. A contact
   drop-shadow grounds the float. Hover lifts the surface (transform, not
   color) and brightens the glass.
   ========================================================================== */
.widget-card {
  position: relative;
  height: 100%;
  min-height: 100%;
  border-radius: 24px;
  /* Depth-tiered contact shadow so near cards ground hardest. */
  filter: var(--w-contact-mid);
  transform:
    rotateX(var(--w-rx))
    rotateY(var(--w-ry))
    translateZ(var(--w-lift));
  transform-style: preserve-3d;
  /* Individual property transitions — NEVER `transition: all`. The parallax
     transform is driven live by the rAF loop, so we don't transition it.   */
  transition:
    filter 320ms var(--w-ease-hover);
  will-change: transform;
}
.widget-card[data-depth="near"] { filter: var(--w-contact-near); }
.widget-card[data-depth="far"]  { filter: var(--w-contact-far); }

/* The face is the actual glass surface — separate layer so the contact
   drop-shadow sits on the outer article, not the glass itself.            */
.widget-card__face {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: var(--w-sp-3);
  padding: clamp(16px, 1.8vw, 24px);
  border-radius: inherit;
  background: var(--w-glass);
  border: 1px solid var(--w-glass-border);
  -webkit-backdrop-filter: blur(12px) saturate(160%);
  backdrop-filter: blur(12px) saturate(160%);
  box-shadow: var(--w-shadow-card);
  overflow: hidden;
  transition:
    background-color 280ms var(--w-ease-hover),
    border-color 280ms var(--w-ease-hover),
    box-shadow 280ms var(--w-ease-hover),
    transform 220ms var(--w-ease-back);
}
/* Sheen — a diagonal light streak across the glass, the visionOS facet. */
.widget-card__sheen {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.14) 0%,
    rgba(255, 255, 255, 0.04) 28%,
    transparent 52%,
    transparent 100%
  );
  opacity: 0.9;
  mix-blend-mode: screen;
}
.widget-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--w-sp-2);
}
.widget-card__label {
  font-size: var(--w-step--1);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--w-text-dim);
}
.widget-card__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--w-iris-bright);
  box-shadow: 0 0 8px var(--w-iris-glow);
}
.widget-card__body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--w-sp-3);
}

/* Hover lifts the surface and brightens the glass — transform, not color. */
.widget-card:hover .widget-card__face {
  background-color: var(--w-glass-deep);
  border-color: var(--w-glass-edge);
  box-shadow: var(--w-shadow-card-lift);
  transform: translateZ(8px);
}
.widget-card:focus-within .widget-card__face {
  border-color: var(--w-iris-bright);
}

/* Static (reduced motion) — flatten the parallax entirely. */
.widget-stage.is-static .widget-card,
.widget-stage.is-static .widget-card[data-depth] {
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .widget-card,
  .widget-card[data-depth] {
    transform: none !important;
    filter: var(--w-contact-mid);
  }
  .widget-card:hover .widget-card__face { transform: none; }
}

/* All numeric values align columns — the dashboard demand. */
.widget-num {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

/* ==========================================================================
   Weather widget
   ========================================================================== */
.widget-weather__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--w-sp-3);
}
.widget-weather__temp {
