}
.widget-weather__cond {
  display: flex;
  align-items: center;
  gap: var(--w-sp-2);
  font-size: var(--w-step--1);
  color: var(--w-text-dim);
  text-align: right;
}
.widget-weather__city {
  margin: 0;
  font-size: var(--w-step--1);
  color: var(--w-text-faint);
