.widget-weather__cond .widget-ico { stroke: var(--w-aqua); }
.widget-hourly {
  list-style: none;
  margin: var(--w-sp-2) 0 0;
  padding: var(--w-sp-3) 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.10);
