  align-items: center;
  gap: 6px;
  flex: 1;
}
.widget-hourly__hour {
  font-size: 0.68rem;
  color: var(--w-text-faint);
  letter-spacing: 0.04em;
}
.widget-hourly__icon .widget-ico { width: 1.1em; height: 1.1em; }
.widget-hourly__temp { font-size: 0.82rem; color: var(--w-text); }

/* ==========================================================================
   Schedule widget
   ========================================================================== */
.widget-schedule__title {
  margin: 0;
  font-size: var(--w-step-1);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--w-text);
