  color: var(--w-iris-bright);
  font-weight: 600;
  letter-spacing: 0.02em;
}
.widget-meetings {
  list-style: none;
  margin: var(--w-sp-2) 0 0;
  padding: var(--w-sp-3) 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.10);
  display: flex;
  flex-direction: column;
  gap: var(--w-sp-2);
