}
.widget-bar {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  height: 100%;
  justify-content: flex-end;
}
.widget-bar__fill {
  width: 100%;
  max-width: 14px;
  height: var(--w-bar, 50%);
  min-height: 6px;
  border-radius: 4px 4px 2px 2px;
  background: linear-gradient(
    180deg,
    var(--w-iris-bright) 0%,
    var(--w-iris) 55%,
    var(--w-iris-soft) 100%
  );
  box-shadow:
    0 0 1px rgba(255, 255, 255, 0.25),
    0 0 10px var(--w-iris-soft);
}
.widget-bar__day {
  font-size: 0.64rem;
  color: var(--w-text-faint);
  letter-spacing: 0.02em;
}

/* ==========================================================================
   Music widget
   ========================================================================== */
.widget-music__head {
  display: flex;
  align-items: center;
  gap: var(--w-sp-3);
}
.widget-music__art {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--w-iris) 0%, #a855f7 100%);
  box-shadow: 0 6px 16px var(--w-iris-soft);
}
.widget-music__glyph {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: #fff;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.widget-music__meta { min-width: 0; }
.widget-music__track {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--w-text);
  text-wrap: pretty;
}
.widget-music__artist {
  margin: 2px 0 0;
  font-size: 0.75rem;
  color: var(--w-text-faint);
}
.widget-music__bar {
  margin-top: var(--w-sp-1);
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}
.widget-music__progress {
  display: block;
  height: 100%;
  width: var(--w-prog, 49%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--w-iris-bright), var(--w-aqua));
}
.widget-music__time {
  display: flex;
  justify-content: space-between;
  font-size: 0.7rem;
  color: var(--w-text-faint);
}
.widget-music__dur { color: var(--w-text-dim); }
.widget-music__controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--w-sp-4);
  margin-top: var(--w-sp-1);
}
.widget-music__btn {
  display: block;
  border-radius: 50%;
  background: var(--w-glass-faint);
  border: 1px solid rgba(255, 255, 255, 0.14);
}
.widget-music__btn--prev,
.widget-music__btn--next {
  width: 28px;
  height: 28px;
}
.widget-music__btn--play {
  width: 40px;
  height: 40px;
  background: var(--w-iris);
  border-color: transparent;
  box-shadow: 0 6px 18px var(--w-iris-soft);
  position: relative;
}
.widget-music__btn--play::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-40%, -50%);
  border-style: solid;
  border-width: 6px 0 6px 10px;
  border-color: transparent transparent transparent #fff;
}

/* ==========================================================================
   Health widget — activity ring
   ========================================================================== */
.widget-health__ring {
  position: relative;
  width: 96px;
  height: 96px;
  margin: 0 auto;
  display: grid;
  place-items: center;
}
.widget-ring { width: 100%; height: 100%; transform: rotate(-90deg); }
.widget-ring__track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.10);
  stroke-width: 10;
}
.widget-ring__value {
  fill: none;
  stroke: var(--w-iris-bright);
  stroke-width: 10;
  stroke-linecap: round;
  stroke-dasharray: 314.16;
  stroke-dashoffset: calc(314.16 - var(--w-ring, 232));
  filter: drop-shadow(0 0 6px var(--w-iris-glow));
}
.widget-ring__pct {
  position: absolute;
  font-size: var(--w-step-1);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--w-text);
}
.widget-health__ring-label {
  margin: var(--w-sp-2) 0 0;
  text-align: center;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--w-text-faint);
}
.widget-health__steps {
  text-align: center;
  margin-top: var(--w-sp-1);
}
.widget-health__count {
  font-size: var(--w-step-1);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--w-text);
}
.widget-health__goal {
  display: block;
  font-size: 0.7rem;
  color: var(--w-text-faint);
}

/* ==========================================================================
   Air & sun widget
   ========================================================================== */
.widget-air {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--w-sp-3);
}
.widget-air__cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: var(--w-sp-2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.widget-air__cell:last-child { border-bottom: 0; padding-bottom: 0; }
.widget-air__value {
  font-size: var(--w-step-1);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--w-text);
}
.widget-air__unit {
  font-size: 0.5em;
  color: var(--w-text-faint);
  margin-left: 4px;
  font-weight: 400;
}
.widget-air__label {
  font-size: 0.72rem;
  color: var(--w-text-dim);
  letter-spacing: 0.02em;
}

/* ==========================================================================
   Timer widget
   ========================================================================== */
.widget-timer__remain {
  margin: 0;
  font-size: var(--w-step-3);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--w-text);
}
.widget-timer__task {
  margin: 0;
  font-size: 0.8rem;
  color: var(--w-text-dim);
}
.widget-timer__bar {
  margin-top: var(--w-sp-2);
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.10);
  overflow: hidden;
}
.widget-timer__progress {
  display: block;
  height: 100%;
  width: var(--w-prog, 62%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--w-rose), var(--w-iris-bright));
}

/* ==========================================================================
   Messages widget
   ========================================================================== */
.widget-msg__head {
  display: flex;
  align-items: baseline;
  gap: var(--w-sp-2);
}
.widget-msg__count {
  font-size: var(--w-step-2);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--w-text);
}
.widget-msg__unit {
  font-size: 0.72rem;
  color: var(--w-text-faint);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.widget-msgs {
  list-style: none;
  margin: var(--w-sp-2) 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--w-sp-2);
}
.widget-msg {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px var(--w-sp-2);
  padding: var(--w-sp-2) 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.widget-msg:first-child { border-top: 0; padding-top: 0; }
.widget-msg__from {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--w-text);
  grid-column: 1;
}
.widget-msg__time {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: start;
  font-size: 0.7rem;
  color: var(--w-text-faint);
}
.widget-msg__preview {
  grid-column: 1;
  font-size: 0.74rem;
  color: var(--w-text-dim);
  text-wrap: pretty;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.widget-foot {
  padding: clamp(48px, 10vh, 88px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 72px);
  text-align: center;
  color: var(--w-text-dim);
  text-wrap: pretty;
}
.widget-foot__brand {
  margin: 0 0 var(--w-sp-2);
  font-size: var(--w-step-1);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--w-text);
}
.widget-foot__line { margin: 0 0 var(--w-sp-2); font-size: 0.85rem; }
.widget-foot__copy { margin: 0; font-size: 0.75rem; color: var(--w-text-faint); }

/* ==========================================================================
   Responsive — honest at 360px, composed at 1440px+
   720 / 900 / 1200 px breakpoints (std checklist: 3+ media queries).
   ========================================================================== */
@media (max-width: 900px) {
  .widget-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  /* Collapse bento spans to fit the narrower grid; flatten deep parallax. */
  .widget-cell {
    grid-column: span min(var(--w-span-col, 2), 2);
  }
  .widget-card[data-depth="near"] { filter: var(--w-contact-mid); }
  .widget-stage { perspective: 1000px; min-height: auto; }
}

@media (max-width: 720px) {
  .widget-hero { padding-bottom: var(--w-sp-6); }
  .widget-title { font-size: clamp(2.6rem, 13vw, 4rem); }
  .widget-grid {
    grid-template-columns: 1fr;
    gap: var(--w-sp-3);
  }
  .widget-cell {
    grid-column: span 1;
    grid-row: span 1;
  }
  .widget-stage {
    perspective: 800px;
    padding: var(--w-sp-3);
    border-radius: 24px;
  }
  .widget-stage-meta {
    flex-wrap: wrap;
    gap: var(--w-sp-2);
  }
  .widget-stage-meta__hint { margin-left: 0; width: 100%; }
  /* On the smallest screens flatten the tilt entirely — suspension would
     just obscure the content. The dashboard reads flat and clean.        */
  .widget-card[data-depth] { filter: var(--w-contact-far); }
}

@media (min-width: 1200px) {
  /* On wide screens, let the field breathe and the depth expand. */
  .widget-stage {
    max-width: 1320px;
    perspective: 1400px;
    padding: clamp(32px, 3vw, 56px);
  }
  .widget-grid { gap: clamp(18px, 1.8vw, 26px); }
  .widget-card__face { padding: clamp(20px, 1.8vw, 30px); }
}

/* ==========================================================================
   Touch / coarse pointer — parallax is pointer-driven and meaningless on a
   touch device with no hover; the hook still runs but the effect is gentle.
   Here we also widen tap targets implicitly via the larger padding above.
   ========================================================================== */
@media (pointer: coarse) {
  .widget-stage { perspective: 1000px; }
  .widget-card[data-depth="near"] { filter: var(--w-contact-mid); }
}
